def generate_candidates(
    ell: int, m: int
) -> list[tuple[list[tuple[int, int]], list[tuple[int, int]]]]:
    """Generate candidate (A_terms, B_terms) pairs for given lattice dimensions."""
    candidates = []
    seen = set()
    import math

    def _add(a_terms, b_terms):
        """Add candidate if not a duplicate."""
        key = (tuple(sorted(a_terms)), tuple(sorted(b_terms)))
        if key not in seen:
            seen.add(key)
            candidates.append((list(a_terms), list(b_terms)))

    # --- Helpers ---
    def get_units_and_divisors(n):
        """Get units and small divisors for single-term exponents."""
        res = set()
        for i in range(1, n):
            if math.gcd(i, n) == 1: res.add(i)
        for i in range(2, n):
            if n % i == 0: res.add(i)
        for i in [1, 2, 3, 4, 5]:
            if i < n: res.add(i)
        return sorted(list(res))

    def get_doubling_pairs(n):
        """Get (u, 2u) pairs."""
        pairs = set()
        # Units and small numbers
        bases = set([i for i in range(1, n) if math.gcd(i, n) == 1])
        for i in range(1, min(n, 12)): bases.add(i)
        for u in bases:
            v = (2 * u) % n
            if v != 0 and v != u:
                pairs.add(tuple(sorted((u, v))))
        return sorted(list(pairs))

    def get_structured_pairs(n):
        """Get exponent pairs (u,v) emphasizing doubling and gaps."""
        pairs = set(get_doubling_pairs(n))
        # Bases for gaps
        bases = [i for i in range(1, n) if math.gcd(i, n) == 1]
        for u in bases:
            for g in [3, 5, 7, 9, n//2]:
                v = (u + g) % n
                if v != 0 and v != u:
                    pairs.add(tuple(sorted((u, v))))
        return sorted(list(pairs))

    # Precompute lists
    a_vals = get_units_and_divisors(ell)
    d_vals = get_units_and_divisors(m)

    y_doubling = get_doubling_pairs(m)
    x_doubling = get_doubling_pairs(ell)

    y_pairs = get_structured_pairs(m)
    x_pairs = get_structured_pairs(ell)

