    x_pairs.sort(key=sum)

    for a in a_vals[:5]:
        for yp in y_pairs:
            A = [(a, 0), (0, yp[0]), (0, yp[1])]
            for d in d_vals[:5]:
                # Sample x_pairs with a stride to get better coverage
                # Take first 10 (small) plus a sparse sample of the rest
                targets = x_pairs[:10] + x_pairs[10::5] 
                for xp in targets[:20]:
